import{_ as t,o as a,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-06-24","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-06-24","outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-06-24.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-06-24.md","lastUpdated":null}'),o={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-06-24.md"};function s(i,e,n,c,p,u){return a(),l("div",null,[...e[0]||(e[0]=[r('<p>I&#39;ll write out the meeting summary in Chinese based on the subtitle content.--- title: Ceph RGW Refactoring Meeting 2026-06-24 date: 2026-07-10 updated: 2026-07-11 tags:</p><ul><li>RGW</li><li>测试</li><li>会议纪要</li><li>CI/CD categories:</li><li>视频总结 subtitle: Ceph_RGW_Refactoring_Meeting_2026-06-24</li></ul><hr><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 RGW 重构例会围绕即将发布的 umbrella 版本收尾工作、云恢复（cloud restore）流程的异步化改造，以及 S3 tests 迁移到主仓库这三大主题展开。会议参与者包括 Adam、Casey、Matthew、Ali Masarwa 等 RGW 核心开发人员。</p><h2 id="一、umbrella-版本收尾-adam-主持" tabindex="-1">一、Umbrella 版本收尾（Adam 主持） <a class="header-anchor" href="#一、umbrella-版本收尾-adam-主持" aria-label="Permalink to &quot;一、Umbrella 版本收尾（Adam 主持）&quot;">​</a></h2><p>Adam 通报了 umbrella 版本的合并进度，强调本周末（end of the week）是最后的合并窗口。目前 Matt Cutler 有一个必须合入的分支（must merge branch），需要在截止前完成。</p><p>会议就以下几个待处理项进行了讨论和确认：</p><ul><li><p><strong>S3 select 的 back port</strong>：Adam 计划将 S3 select 相关改动 back port 到 umbrella。经现场确认，<code>ceph umbrella</code> 与 <code>ceph master</code> 分支上的 S3 tests 完全一致、并未 diverge，因此 back port 不存在分支不一致的障碍。</p></li><li><p><strong>Global OIDC 特性</strong>：有成员提出一个已被 Preetha 批准、正在等待 Casey 最终确认（give his blessings）的 global OIDC PR，建议纳入 umbrella。Casey 明确表示该特性此前并未计划纳入 umbrella，也未被列为 blocker，且现在时间点已经偏晚，因此暂不考虑纳入。</p></li><li><p><strong>Ali Masarwa 的工作</strong>：Ali 提到他终于合并了此前一直在做的分支，但未说明具体内容。此前 Ali 的相关工作因反复出现 Teuthology 测试问题而未能赶上 umbrella 的合并窗口。会中定位到两个相关 PR：一个是 Ali review 过、已有指向 umbrella 的 open backport；另一个是 Ali 自己的 global cores 工作，已经 merge，但 backport 只指向 tentacle（tracker issue 显示 pending backport but only to tentacle）。Adam 承诺会 double-check 并在缺失时补做 backport。</p></li><li><p><strong>Objecter 修复</strong>：有成员指出一个存在已久、自 Reef 版本起就损坏、目前仍在等待 Casey 处理的 objecter fix。该问题已存在数月，虽然目前不算 blocker，但可以 back port 到下一个 point release。Casey 表示会去看。</p></li><li><p><strong>GitHub 查询链接</strong>：议程中链接了两个里程碑查询——umbrella milestone（3 个 open PR）与 21.10 milestone（1 个 open PR），供后续跟踪。</p></li><li><p><strong>9.2 版本崩溃问题</strong>：有成员反馈 9.2 在执行 zone reload 等操作时出现 crash，报错涉及 data log back end，出现 pthread mutex lock 相关的 segfault。Casey 指出该 9.2 相关讨论属于 downstream 范畴，应转到 downstream Slack 讨论。</p></li></ul><p><strong>结论</strong>：Adam 发出「最后合并通知」（last call），提醒所有人如果有希望进入 umbrella 的改动需尽快提交。</p><h2 id="二、异步-curl-客户端与云恢复改造-matthew-主持" tabindex="-1">二、异步 curl 客户端与云恢复改造（Matthew 主持） <a class="header-anchor" href="#二、异步-curl-客户端与云恢复改造-matthew-主持" aria-label="Permalink to &quot;二、异步 curl 客户端与云恢复改造（Matthew 主持）&quot;">​</a></h2><p>Matthew 汇报了将 cloud restore 异步化的工作进展。核心思路是引入 co-routines，并在 co-routines 处理各个 shard 的同时对 FIFO 队列进行 trim。</p><p><strong>遇到的关键问题</strong>：原有 PR 会对全局共享的 HTTP manager 产生 blocking operations，而该 manager 同时被 multi-site 的异步复制（async replication）所共享，这是一个严重隐患。</p><p><strong>解决方案验证</strong>：根据 Casey 提出的建议，Matthew 在一个独立分支中基于 async curl client 重新实现了整套逻辑，整合了 Casey 的 lease PR 与 async curl client。为支持该场景，他对 curl client 做了少量扩展，补齐了缺失的能力，改动量不大。</p><p>Matthew 对该方案进行了充分测试并确认可用：</p><ul><li>通过了本地 topology test。</li><li>向一个填充了 50,000 个对象的 bucket 发起恢复，对接 AWS endpoint 完成全量 restore。</li><li>在真实工作负载下验证了与 AWS S3 的正常通信。</li><li>分别在 AWS S3、Backblaze B2、MinIO 三种 S3 后端上验证行为一致。</li></ul><p><strong>讨论与决定</strong>：</p><ul><li>Casey 认为不宜在第一版 PR 中包含 async curl 改动，以免阻塞其他修复的合入，且 async curl 部分仍需更充分的 review。</li><li>与会者一致认为，先在 cloud restore 场景中落地 async curl client 是一个很好的首个可用实现——受众是使用 cloud restore 的运维人员，覆盖面小、影响可控（minimal impact）。</li><li>关于向 multi-site 推广，Matthew 表示存疑，因为 multi-site 甚至不使用 asio 作为其 runtime，集成难度较大。</li><li>各方认可 async curl client 在 cloud transition 与 cloud restore 场景均有应用价值，其他场景则有待评估（to be determined）。</li></ul><p><strong>结论</strong>：第一版 PR 暂不包含 curl 改动，仅保留 blocking 部分；随后以独立的 follow-up PR 处理 blocking 问题。该工作暂不进入 umbrella，先留在 main 分支；待第二部分合入后，再讨论是否 backport 到 umbrella。</p><p>此外，Matthew 感谢了对 PR 67725 的 review。该 PR 近期因新合入的 GCM 代码以及 Gabriel 的 dedupe 改动做了 rework，现已就绪，可与现有代码良好协同。</p><h2 id="三、s3-tests-迁入主仓库-casey-通报" tabindex="-1">三、S3 tests 迁入主仓库（Casey 通报） <a class="header-anchor" href="#三、s3-tests-迁入主仓库-casey-通报" aria-label="Permalink to &quot;三、S3 tests 迁入主仓库（Casey 通报）&quot;">​</a></h2><p>Casey 宣布 Adam 主导的、将 S3 tests 迁移进主仓库的改动已经 merged，并已在 RGW devel 渠道发布公告。</p><p><strong>对开发者的影响</strong>：如果你有正在修改 S3 tests 的 outstanding PR，需要执行 rebase，并将测试迁移到仓库内对应位置。</p><p><strong>价值</strong>：此举将大幅简化针对带测试改动的 PR 的 QA 流程，并有利于后续的 backports。Casey 再次对 Adam 表示感谢。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>Adam：确认 S3 tests 与 umbrella/master 分支一致性后，完成 S3 select 到 umbrella 的 back port；double-check Ali 的 global cores 工作是否已 backport，缺失则补做；直接接管 S3 tests 迁入仓库的相关工作。</li><li>Casey：处理长期挂起的 objecter fix，评估其 back port 到下一个 point release 的可行性。</li><li>Matthew：以不含 curl 改动的第一版 PR 先行合入，随后提交处理 blocking 问题的 follow-up PR；待第二部分完成后再讨论是否 backport 到 umbrella。</li><li>全体：如有希望纳入 umbrella 的改动，本周末前为最后提交窗口；9.2 崩溃问题移交 downstream Slack 跟进；带 S3 tests 改动的 open PR 需 rebase 并迁移测试位置。</li></ul>',26)])])}const b=t(o,[["render",s]]);export{m as __pageData,b as default};
